import { Decimal } from '../domain/shared/decimal.ts';
import type { RecordTransactionCommand } from '../application/RecordTransactionUseCase.ts';

/**
 * Adaptador de entrada: convierte cadenas del contrato de E/S en tipos de dominio.
 * Los campos destino son numéricos sin signo (PIC 9(5), PIC 9999.99), por lo que
 * el signo de la entrada se descarta (se conserva el valor absoluto).
 * @rule R-001
 * @rule R-002
 */
export class StringInputMapper {
  toCommand(input: Record<string, string>): RecordTransactionCommand {
    return {
      fromAccount: StringInputMapper.toDecimal(input['from_account']),
      toAccount: StringInputMapper.toDecimal(input['to_account']),
      amount: StringInputMapper.toDecimal(input['amount']),
    };
  }

  private static toDecimal(raw: string | undefined): Decimal {
    const trimmed = (raw ?? '0').trim();
    const unsigned = trimmed.replace(/^[+-]\s*/, '');
    if (unsigned === '') {
      return Decimal.of('0');
    }
    return Decimal.of(unsigned.replace(/^0+(?=\d)/, ''));
  }
}
